const merge = require("webpack-merge");
const common = require("./webpack.common.js");
const webpack = require("webpack");

const TerserPlugin = require("terser-webpack-plugin");

module.exports = merge(common, {
  mode: "production",

  output: {
    // Content hashes let public/_headers serve /dist/* as immutable for a year:
    // a changed bundle gets a new URL, so no browser can pin a stale one.
    // index.html is generated by HtmlWebpackPlugin and references these names.
    filename: "dist/[name].[contenthash].js",
    chunkFilename: "dist/[name].[contenthash].js",
  },

  plugins: [
    new webpack.DefinePlugin({
      "process.env.NODE_ENV": '"production"',
    }),
  ],

  optimization: {
    minimizer: [
      new TerserPlugin({
        test: /\.js(\?.*)?$/i,
        terserOptions: {
          compress: {
            drop_console: true,
            keep_fargs: false,
            ecma: 2020,
            toplevel: true,
            module: true,
          },
          ecma: 2020,
        },
      }),
    ],
    minimize: true,
  },
});
